CREATE COLUMN TABLE "TEST_AP"."ODMW" ("Code" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "CategoryId" INTEGER CS_INT, "DestPath" NCLOB MEMORY THRESHOLD 1000, "Extantion" NVARCHAR(5), "UserSign" SMALLINT CS_INT, "Delim" NVARCHAR(10) DEFAULT 'T', "InclTitle" NVARCHAR(1) DEFAULT 'N', "SetExp" NVARCHAR(1) DEFAULT 'N', "NewRecs" NVARCHAR(1) DEFAULT 'N', "Summary" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ODMW_NAME" ON "TEST_AP"."ODMW" ( "Name" ASC )